/**
 * Idempotent seed: safe to run any number of times.
 * - Users are upserted by email (password refreshed from SEED_PASSWORD).
 * - The activity is found by scenarioKey or created.
 * - Assignments are upserted on (activityId, learnerId).
 * - Demo attempts are generated by replaying action lists through the real simulation engine,
 *   so their decision histories always match the engine's rules.
 *   A demo attempt is identified by its fixed seed: re-running updates it in place.
 *   Assignments that already have other (real) attempts are left alone.
 *
 * Run with: npm run db:seed
 */
import "dotenv/config";
import bcrypt from "bcryptjs";
import type { AssignmentStatus, Prisma } from "../src/generated/prisma/client";
import { apply, start } from "../src/lib/simulation/engine";
import { hardwareTroubleshooting as scenario } from "../src/lib/simulation/scenarios/hardware-troubleshooting";
import type { SimulationState } from "../src/lib/simulation/types";
import { prisma } from "../src/server/db";

const DAY = 24 * 60 * 60 * 1000;
const daysAgo = (days: number, hour = 10) => {
  const date = new Date(Date.now() - days * DAY);
  date.setHours(hour, 0, 0, 0);
  return date;
};

type FaultId = "FAULTY_RAM" | "FAILING_PSU" | "CPU_OVERHEATING";

/** A seed that makes the engine pick `fault` (the engine uses faults[seed % faults.length]). */
function seedFor(fault: FaultId, base: number): number {
  const index = scenario.faults.findIndex((candidate) => candidate.id === fault);
  return base * scenario.faults.length + index;
}

/** Plays the actions through the engine and returns the resulting state. */
function replay(fault: FaultId, base: number, actionIds: string[]): SimulationState {
  let state = start(scenario, seedFor(fault, base));
  for (const actionId of actionIds) {
    state = apply(scenario, state, actionId).state;
  }
  return state;
}

