// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  const password = process.env.SEED_PASSWORD;
  if (!password || password.length < 8) {
    throw new Error("SEED_PASSWORD must be set in .env and be at least 8 characters.");
  }
  const passwordHash = await bcrypt.hash(password, 10);

  const admin = await prisma.user.upsert({
    where: { email: ADMIN.email },
    update: { passwordHash, role: "ADMIN", status: "ACTIVE" },
    create: { ...ADMIN, passwordHash, role: "ADMIN", status: "ACTIVE", createdAt: daysAgo(60) },
  });

  const learnerIdByEmail = new Map<string, string>();
  for (const [index, learner] of LEARNERS.entries()) {
    const user = await prisma.user.upsert({
      where: { email: learner.email },
      update: { passwordHash },
      create: {
        name: learner.name,
        email: learner.email,
        cohort: learner.cohort,
        role: "LEARNER",
        status: learner.active ? "ACTIVE" : "INACTIVE",
        passwordHash,
        createdAt: daysAgo(45 - index),
        lastActiveAt: learner.active ? daysAgo(index % 5) : daysAgo(30),
      },
    });
    learnerIdByEmail.set(learner.email, user.id);
  }

  let activity = await prisma.activity.findFirst({ where: { scenarioKey: scenario.key } });
  if (!activity) {
    activity = await prisma.activity.create({
      data: {
        title: scenario.title,
        description:
          "A lab workstation won't work properly. Investigate the symptoms safely, find the hidden hardware fault and repair it.",
        type: "SIMULATION",
        scenarioKey: scenario.key,
        estimatedMinutes: 20,
        createdById: admin.id,
        createdAt: daysAgo(30),
      },
    });
    await prisma.auditLog.create({
      data: {
        actorId: admin.id,
        action: "activity.created",
        entityType: "Activity",
        entityId: activity.id,
        metadata: { title: activity.title },
        createdAt: daysAgo(30),
      },
    });
  }

  let created = 0;
  let refreshed = 0;
  for (const plan of PLAN) {
    const learnerId = learnerIdByEmail.get(plan.email)!;
    const assignedAt = daysAgo(plan.assignedDaysAgo, 9);
    const dueDate = plan.dueInDays === null ? null : daysAgo(-plan.dueInDays, 17);
    const state = plan.attempt ? replay(plan.attempt.fault, plan.attempt.seedBase, plan.attempt.actions) : null;
    const completed = state?.status === "COMPLETED";
    if (completed && plan.completedDaysAgo === undefined) {
      throw new Error(`Plan for ${plan.email} completes the simulation but has no completedDaysAgo.`);
    }
    const completedAt = completed ? daysAgo(plan.completedDaysAgo!, 14) : null;
    const status: AssignmentStatus = completed ? "COMPLETED" : state ? "IN_PROGRESS" : "NOT_STARTED";

    const existing = await prisma.assignment.findUnique({
      where: { activityId_learnerId: { activityId: activity.id, learnerId } },
      include: { attempts: { select: { id: true, seed: true } } },
    });
    const demoAttempt = state ? existing?.attempts.find((attempt) => attempt.seed === state.seed) : undefined;
    const hasRealAttempts = (existing?.attempts ?? []).some((attempt) => attempt.id !== demoAttempt?.id);
    if (hasRealAttempts) continue; // a real learner has worked on this: leave it alone

    const assignment = await prisma.assignment.upsert({
      where: { activityId_learnerId: { activityId: activity.id, learnerId } },
      update: { status, dueDate, completedAt },
      create: { activityId: activity.id, learnerId, status, assignedAt, dueDate, completedAt },
    });
    if (!existing) {
      await prisma.auditLog.create({
        data: {
          actorId: admin.id,
          action: "assignment.created",
          entityType: "Assignment",
          entityId: assignment.id,
          metadata: { learnerId, activityId: activity.id, title: activity.title, added: 1 },
          createdAt: assignedAt,
        },
      });
    }

    if (!state) continue;
    const startedAt = completedAt ? new Date(completedAt.getTime() - 25 * 60 * 1000) : daysAgo(1, 15);
    const data = {
      state: state as unknown as Prisma.InputJsonValue,
      score: state.score,
      startedAt,
      completedAt,
    };

    if (demoAttempt) {
      await prisma.simulationAttempt.update({ where: { id: demoAttempt.id }, data });
      refreshed += 1;
      continue;
    }

    const attempt = await prisma.simulationAttempt.create({
      data: { ...data, assignmentId: assignment.id, scenarioKey: scenario.key, seed: state.seed },
    });
    created += 1;
    await prisma.auditLog.create({
      data: {
        actorId: learnerId,
        action: "simulation.started",
        entityType: "SimulationAttempt",
        entityId: attempt.id,
        metadata: { assignmentId: assignment.id },
        createdAt: startedAt,
      },
    });
    if (completedAt) {
      await prisma.auditLog.create({
        data: {
          actorId: learnerId,
          action: "simulation.completed",
          entityType: "SimulationAttempt",
          entityId: attempt.id,
          metadata: { assignmentId: assignment.id, score: state.score },
          createdAt: completedAt,
        },
      });
    }
  }

  const counts = {
    users: await prisma.user.count(),
    activities: await prisma.activity.count(),
    assignments: await prisma.assignment.count(),
    attempts: await prisma.simulationAttempt.count(),
    auditLogs: await prisma.auditLog.count(),
  };
  console.log(`Seed complete. Demo attempts created: ${created}, refreshed: ${refreshed}.`, counts);
  console.log(`Sign in as ${ADMIN.email} (admin) or lerato@pathway.test (learner) with SEED_PASSWORD.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
